-- =====================================================================
--  Sunrise Dental Clinic - V3 seed data
--
--      mysql -u root -p < database/V3__seed.sql
--
--  PASSWORDS
--  password_hash holds PBKDF2-HMAC-SHA256 at 210,000 iterations with a
--  per-user 16-byte random salt, generated by
--      java -cp target/classes lk.icbt.dentalclinic.security.PasswordHasher
--  No plaintext and no bare digest is ever stored. The demo passwords
--  below are documented here only because this is coursework with a
--  throwaway database; a real deployment would force a change on first
--  login.
--
--      admin        Admin@123      ADMIN
--      dr.perera    Dentist@123    DENTIST
--      dr.silva     Dentist@456    DENTIST
--      kasun.f      Patient@123    PATIENT
--      nadeesha.w   Patient@456    PATIENT
-- =====================================================================

USE sunrise_clinic;


-- ---------------------------------------------------------------------
-- Roles. RECEPTIONIST from the reference schema is deliberately folded
-- into ADMIN - it had no behaviour of its own (assumption A3).
-- ---------------------------------------------------------------------
INSERT INTO roles (code, description) VALUES
    ('ADMIN',   'Clinic administrator - full access to all records and reports'),
    ('DENTIST', 'Dentist - own schedule and assigned patients'),
    ('PATIENT', 'Patient - self-service booking and own records');


-- ---------------------------------------------------------------------
-- Clinic settings, read by fn_appointment_total and the booking
-- validator instead of being hard-coded in Java.
--
-- tax.rate is 0 because dental healthcare services are VAT-exempt in
-- Sri Lanka. The setting and the bill column exist so a rate can be
-- applied without a schema change if that ever alters.
-- ---------------------------------------------------------------------
INSERT INTO clinic_settings (setting_key, setting_value, description) VALUES
    ('consultation.fee',  '2500.00', 'Standard consultation fee added to every bill (LKR)'),
    ('tax.rate',          '0.0000',  'Tax applied to the discounted subtotal (0 = exempt)'),
    ('discount.max.pct',  '25.00',   'Maximum discount as a percentage of the subtotal'),
    ('clinic.open',       '08:00',   'Earliest bookable appointment time'),
    ('clinic.close',      '20:00',   'Latest bookable appointment time'),
    ('slot.minutes',      '30',      'Appointment slots must fall on this boundary'),
    ('clinic.name',       'Sunrise Dental Clinic', 'Name printed on receipts'),
    ('clinic.address',    '221 Galle Road, Colombo 03', 'Address printed on receipts');


