-- ---------------------------------------------------------------------
-- Treatments. `family` is what PricingStrategyFactory resolves on in M4,
-- so adding a treatment to an existing family needs no new Java code.
-- ---------------------------------------------------------------------
INSERT INTO treatments (code, name, family, description, base_cost, duration_minutes) VALUES
    ('CONSULT', 'Consultation',          'CONSULTATION', 'General dental examination and advice',        0.00,    20),
    ('CLEAN',   'Scaling and Polishing', 'CLEANING',     'Removal of plaque and calculus, polish',    5000.00,    30),
    ('FILL',    'Composite Filling',     'FILLING',      'Tooth-coloured restoration, single surface', 7500.00,    45),
    ('EXTRACT', 'Simple Extraction',     'EXTRACTION',   'Non-surgical removal of a single tooth',    10000.00,    30),
    ('RCT',     'Root Canal Treatment',  'ROOT_CANAL',   'Endodontic treatment, single canal',        25000.00,    90),
    ('CROWN',   'Porcelain Crown',       'PROSTHETIC',   'Full-coverage porcelain crown',             35000.00,    60),
    ('WHITEN',  'Teeth Whitening',       'COSMETIC',     'In-clinic bleaching, single session',       18000.00,    60);


