-- ---------------------------------------------------------------------
-- Sample appointments, so the reports and the dentist workload view
-- return real numbers on a fresh install.
--
-- Inserting these also exercises trg_appointment_audit_ins: the
-- verification block at the end of this file asserts that audit_log has
-- one row per appointment.
-- ---------------------------------------------------------------------
SET @admin_id = (SELECT user_id FROM users WHERE username = 'admin');
SET @yr       = YEAR(CURDATE());

INSERT INTO appointments (appointment_no, patient_id, dentist_id, treatment_id,
                          appointment_date, appointment_time, status, notes, created_by) VALUES
    (CONCAT('APT-', @yr, '-0001'),
     (SELECT patient_id   FROM patients   WHERE patient_no = 'PAT-000001'),
     (SELECT dentist_id   FROM dentists   WHERE full_name  = 'Dr. Nimal Perera'),
     (SELECT treatment_id FROM treatments WHERE code       = 'CLEAN'),
     CURDATE() - INTERVAL 7 DAY, '09:00:00', 'COMPLETED', 'Routine six-month clean', @admin_id),

    (CONCAT('APT-', @yr, '-0002'),
     (SELECT patient_id   FROM patients   WHERE patient_no = 'PAT-000002'),
     (SELECT dentist_id   FROM dentists   WHERE full_name  = 'Dr. Anjali Silva'),
     (SELECT treatment_id FROM treatments WHERE code       = 'FILL'),
     CURDATE() - INTERVAL 3 DAY, '14:30:00', 'COMPLETED', 'Upper left first molar', @admin_id),

    (CONCAT('APT-', @yr, '-0003'),
     (SELECT patient_id   FROM patients   WHERE patient_no = 'PAT-000003'),
     (SELECT dentist_id   FROM dentists   WHERE full_name  = 'Dr. Nimal Perera'),
     (SELECT treatment_id FROM treatments WHERE code       = 'EXTRACT'),
     CURDATE() - INTERVAL 1 DAY, '11:00:00', 'CANCELLED', 'Patient rescheduled by telephone', @admin_id),

    (CONCAT('APT-', @yr, '-0004'),
     (SELECT patient_id   FROM patients   WHERE patient_no = 'PAT-000001'),
     (SELECT dentist_id   FROM dentists   WHERE full_name  = 'Dr. Anjali Silva'),
     (SELECT treatment_id FROM treatments WHERE code       = 'RCT'),
     CURDATE() + INTERVAL 2 DAY, '15:00:00', 'BOOKED', 'First of two visits', @admin_id);

-- The four numbers above were assigned by hand, so the sequence must be
-- advanced to match or sp_next_appointment_no would hand out a duplicate.
INSERT INTO appointment_sequence (seq_year, last_number)
VALUES (@yr, 4)
ON DUPLICATE KEY UPDATE last_number = GREATEST(last_number, 4);


-- ---------------------------------------------------------------------
-- One issued bill for the completed cleaning, so the revenue report has
-- data. total_amount is deliberately left at its default: the trigger
-- trg_bill_before_insert computes it.
-- ---------------------------------------------------------------------
INSERT INTO bills (bill_no, appointment_id, consultation_fee, treatment_charge,
                   discount_amount, tax_amount, status, issued_by) VALUES
    (CONCAT('BIL-', @yr, '-0001'),
     (SELECT appointment_id FROM appointments WHERE appointment_no = CONCAT('APT-', @yr, '-0001')),
     2500.00, 5000.00, 0.00, 0.00, 'PAID', @admin_id);

INSERT INTO bill_line_items (bill_id, description, quantity, unit_price, line_total) VALUES
    ((SELECT bill_id FROM bills WHERE bill_no = CONCAT('BIL-', @yr, '-0001')),
     'Consultation', 1, 2500.00, 2500.00),
    ((SELECT bill_id FROM bills WHERE bill_no = CONCAT('BIL-', @yr, '-0001')),
     'Scaling and Polishing', 1, 5000.00, 5000.00);

UPDATE bills SET paid_at = NOW() WHERE bill_no = CONCAT('BIL-', @yr, '-0001');


INSERT INTO schema_version (version, description)
VALUES ('V3', 'Seed data: 3 roles, 8 settings, 5 users, 2 dentists, 3 patients, 7 treatments');


-- ---------------------------------------------------------------------
-- Verification. Every line below should report OK.
-- ---------------------------------------------------------------------
SELECT 'roles'         AS entity, COUNT(*) AS rows_seeded, IF(COUNT(*) = 3, 'OK', 'FAIL') AS result FROM roles
UNION ALL SELECT 'clinic_settings', COUNT(*), IF(COUNT(*) = 8, 'OK', 'FAIL') FROM clinic_settings
UNION ALL SELECT 'users',           COUNT(*), IF(COUNT(*) = 5, 'OK', 'FAIL') FROM users
UNION ALL SELECT 'dentists',        COUNT(*), IF(COUNT(*) = 2, 'OK', 'FAIL') FROM dentists
UNION ALL SELECT 'patients',        COUNT(*), IF(COUNT(*) = 3, 'OK', 'FAIL') FROM patients
UNION ALL SELECT 'treatments',      COUNT(*), IF(COUNT(*) = 7, 'OK', 'FAIL') FROM treatments
UNION ALL SELECT 'help_topics',     COUNT(*), IF(COUNT(*) = 6, 'OK', 'FAIL') FROM help_topics
UNION ALL SELECT 'appointments',    COUNT(*), IF(COUNT(*) = 4, 'OK', 'FAIL') FROM appointments
UNION ALL SELECT 'bills',           COUNT(*), IF(COUNT(*) = 1, 'OK', 'FAIL') FROM bills
UNION ALL SELECT 'bill_line_items', COUNT(*), IF(COUNT(*) = 2, 'OK', 'FAIL') FROM bill_line_items
-- Written entirely by trg_appointment_audit_ins - proof the trigger fired.
UNION ALL SELECT 'audit_log (trigger)', COUNT(*), IF(COUNT(*) = 4, 'OK', 'FAIL') FROM audit_log;

-- Proof that trg_bill_before_insert computed the total: 2500 + 5000 - 0 + 0.
SELECT bill_no, consultation_fee, treatment_charge, total_amount,
       IF(total_amount = 7500.00, 'OK - trigger computed the total', 'FAIL') AS result
FROM bills;
